//! Port of `taky/tests/test_takuser.py` and `taky/tests/test_geo_chat.py` (S-307), plus
//! field-built `TAKUser`/`GeoChat` `as_element` byte-exact against lxml
//! (`fixtures/models_from_fields.json`, generated by `fixtures/gen_models.py`).
#![allow(clippy::unwrap_used, clippy::expect_used)] // test helpers outside #[test] fns

use serde_json::Value;
use taky_common::pyparse::py_float;
use taky_cot::isoparse::isoparse;
use taky_cot::{Event, EventDetail, GeoChat, TakDevice, TakUser, Teams};
use taky_xml::{Element, Node, SerOpts, parse_element, serialize};

/// `test_takuser.py:XML_S`.
const TAKUSER_XML: &str = r#"<event version="2.0" uid="TEST-deadbeef" type="a" how="m-g" time="2021-03-11T15:49:07.138Z" start="2021-03-11T15:49:07.138Z" stale="2021-03-12T15:49:07.138Z"><point lat="0.000000" lon="0.000000" hae="0.0" ce="9999999.0" le="9999999.0"/><detail><takv os="Android" version="10" device="Some Device" platform="python unittest"/><status battery="83"/><uid Droid="JENNY"/><contact callsign="JENNY" endpoint="*:-1:stcp" phone="800-867-5309"/><__group role="Team Member" name="Cyan"/><track course="90.1" speed="10.3"/></detail></event>"#;

/// `test_geo_chat.py:XML_S`.
const GEOCHAT_XML: &str = r#"<event version="2.0" uid="GeoChat.ANDROID-deadbeef.JOKER MAN.563040b9-2ac9-4af3-9e01-4cb2b05d98ea" type="b-t-f" how="h-g-i-g-o" time="2021-02-23T22:28:22.191Z" start="2021-02-23T22:28:22.191Z" stale="2021-02-24T22:28:22.191Z">
  <point lat="1.234567" lon="-3.141592" hae="-25.8" ce="9.9" le="9999999.0"/>
  <detail>
    <__chat parent="RootContactGroup" groupOwner="false" chatroom="JOKER MAN" id="ANDROID-cafebabe" senderCallsign="JENNY">
      <chatgrp uid0="ANDROID-deadbeef" uid1="ANDROID-cafebabe" id="ANDROID-cafebabe"/>
    </__chat>
    <link uid="ANDROID-deadbeef" type="a-f-G-U-C" relation="p-p"/>
    <remarks source="BAO.F.ATAK.ANDROID-deadbeef" to="ANDROID-cafebabe" time="2021-02-23T22:28:22.191Z">test</remarks>
    <__serverdestination destinations="123.45.67.89:4242:tcp:ANDROID-deadbeef"/>
    <marti>
      <dest callsign="JOKER MAN"/>
    </marti>
  </detail>
</event>
"#;

fn parse(s: &str) -> Element {
    parse_element(s.as_bytes(), &taky_cot::limits::STREAM_LIMITS).unwrap()
}

/// `taky/tests/__init__.py:elements_equal` (tag, text, tail, attrib as a dict, children).
fn elements_equal(a: &Element, b: &Element) {
    assert_eq!(a.tag, b.tag);
    assert_eq!(a.text, b.text, "text of {}", a.tag);
    assert_eq!(a.tail, b.tail, "tail of {}", a.tag);
    let (mut x, mut y) = (a.attrs.clone(), b.attrs.clone());
    x.sort();
    y.sort();
    assert_eq!(x, y, "attrib of {}", a.tag);
    assert_eq!(a.children.len(), b.children.len(), "len of {}", a.tag);
    for (c, d) in a.children.iter().zip(&b.children) {
        match (c, d) {
            (Node::Element(c), Node::Element(d)) => elements_equal(c, d),
            (c, d) => assert_eq!(c, d),
        }
    }
}

fn jenny() -> TakUser {
    TakUser {
        callsign: Some("JENNY".into()),
        marker: Some("a".into()),
        group: Some(Teams::Cyan),
        role: Some("Team Member".into()),
        phone: Some("800-867-5309".into()),
        endpoint: Some("*:-1:stcp".into()),
        course: Some(90.1),
        speed: Some(10.3),
        battery: Some("83".into()),
        device: TakDevice {
            os: Some("Android".into()),
            version: Some("10".into()),
            device: Some("Some Device".into()),
            platform: Some("python unittest".into()),
        },
        ..TakUser::default()
    }
}

/// `test_takuser.TAKUserTestcase.test_as_element`.
#[test]
fn test_takuser_as_element() {
    let answer = parse(TAKUSER_XML).find("detail").unwrap().clone();
    elements_equal(&answer, &jenny().to_element().unwrap());
}

/// `test_geo_chat.GeoChatTestcase.test_unmarshall`.
#[test]
fn test_geochat_unmarshall() {
    let event = Event::from_element(&parse(GEOCHAT_XML)).unwrap();
    let Some(EventDetail::GeoChat(chat)) = &event.detail else {
        panic!("expected GeoChat, got {:?}", event.detail)
    };
    assert_eq!(chat.chatroom.as_deref(), Some("JOKER MAN"));
    assert_eq!(chat.chat_parent.as_deref(), Some("RootContactGroup"));
    assert!(!chat.group_owner);
    assert!(!chat.broadcast());
    assert_eq!(chat.src_uid.as_deref(), Some("ANDROID-deadbeef"));
    assert_eq!(chat.src_cs.as_deref(), Some("JENNY"));
    assert_eq!(chat.src_marker.as_deref(), Some("a-f-G-U-C"));
    assert_eq!(chat.message.as_deref(), Some("test"));
    assert_eq!(chat.dst_uid.as_deref(), Some("ANDROID-cafebabe"));
    assert_eq!(chat.dst_team, None);
    // Parsed details go on the wire as the original element (spec §7.5).
    let original = parse(GEOCHAT_XML);
    assert_eq!(
        &chat.to_element().unwrap(),
        original.find("detail").unwrap()
    );
    assert_eq!(chat.marti_cs(), vec![Some("JOKER MAN".to_string())]);
}

/// A field-built GeoChat survives `as_element` → `from_elm` (fields the parser reads back).
#[test]
fn geochat_field_built_round_trip() {
    for (parent, room, team, dst) in [
        ("RootContactGroup", "All Chat Rooms", None, None),
        ("TeamGroups", "Dark Blue", Some(Teams::DarkBlue), None),
        (
            "RootContactGroup",
            "JOKER MAN",
            None,
            Some("ANDROID-cafebabe"),
        ),
    ] {
        let g = GeoChat {
            chatroom: Some(room.into()),
            chat_parent: Some(parent.into()),
            group_owner: true,
            src_uid: Some("ANDROID-deadbeef".into()),
            src_cs: Some("JENNY".into()),
            src_marker: Some("a-f-G-U-C".into()),
            message: Some("hi <there> & ü".into()),
            message_ts: isoparse("2021-02-23T22:28:22.191999"),
            dst_uid: dst.map(str::to_string),
            dst_team: team,
            elm: None,
        };
        let elm = g.to_element().unwrap();
        let back = GeoChat::from_element(&elm).unwrap();
        assert_eq!(back.elm.as_ref(), Some(&elm));
        assert_eq!(
            GeoChat { elm: None, ..back },
            GeoChat {
                // milliseconds are truncated on the wire
                message_ts: isoparse("2021-02-23T22:28:22.191"),
                ..g
            }
        );
    }
}

#[test]
fn field_built_errors() {
    let mut u = jenny();
    u.role = None;
    assert!(u.to_element().is_err()); // ValueError: Missing fields
    let mut u = jenny();
    u.callsign = Some("bad\u{1}".into());
    assert!(u.to_element().is_err()); // lxml ValueError: not XML compatible
    let g = GeoChat {
        chatroom: Some("All Chat Rooms".into()),
        ..GeoChat::default()
    };
    assert!(g.to_element().is_err()); // lxml TypeError: parent is None
}

fn s(c: &Value, k: &str) -> Option<String> {
    c[k].as_str().map(str::to_string)
}

fn f(c: &Value, k: &str) -> Option<f64> {
    c[k].as_str().map(|v| py_float(v).expect("float repr"))
}

fn team(c: &Value, k: &str) -> Option<Teams> {
    c[k].as_str().map(|v| Teams::from_name(v).expect("team"))
}

fn check(kind: &str, i: usize, c: &Value, got: Result<Element, taky_cot::SerializeError>) {
    match (c.get("out").and_then(Value::as_str), got) {
        (Some(want), Ok(e)) => assert_eq!(
            String::from_utf8(serialize(&e, &SerOpts::default())).unwrap(),
            want,
            "{kind} case {i}: {c}"
        ),
        (None, Err(_)) => {}
        (want, got) => panic!("{kind} case {i}: python {want:?}, rust {got:?}; {c}"),
    }
}

/// Field-built `as_element` serialized byte-exact like `etree.tostring`, errors where Python raises.
#[test]
fn field_built_matches_lxml_fixture() {
    let raw = include_str!("fixtures/models_from_fields.json");
    let data: Value = serde_json::from_str(raw).unwrap();
    let users = data["takuser"].as_array().unwrap();
    let chats = data["geochat"].as_array().unwrap();
    assert!(users.len() > 100 && chats.len() > 100);
    for (i, c) in users.iter().enumerate() {
        let u = TakUser {
            callsign: s(c, "callsign"),
            group: team(c, "group"),
            role: s(c, "role"),
            phone: s(c, "phone"),
            xmpp: s(c, "xmpp"),
            endpoint: s(c, "endpoint"),
            course: f(c, "course"),
            speed: f(c, "speed"),
            battery: s(c, "battery"),
            device: TakDevice {
                os: s(c, "os"),
                version: s(c, "version"),
                device: s(c, "device"),
                platform: s(c, "platform"),
            },
            ..TakUser::default()
        };
        check("takuser", i, c, u.to_element());
    }
    for (i, c) in chats.iter().enumerate() {
        let g = GeoChat {
            elm: None,
            chatroom: s(c, "chatroom"),
            chat_parent: s(c, "chat_parent"),
            group_owner: c["group_owner"].as_bool().unwrap(),
            src_uid: s(c, "src_uid"),
            src_cs: s(c, "src_cs"),
            src_marker: s(c, "src_marker"),
            message: s(c, "message"),
            message_ts: c["message_ts"].as_str().map(|t| isoparse(t).unwrap()),
            dst_uid: s(c, "dst_uid"),
            dst_team: team(c, "dst_team"),
        };
        check("geochat", i, c, g.to_element());
    }
}

/// A field-built detail inside an `Event` reaches the wire; an unserializable one is an error.
#[test]
fn event_with_field_built_detail() {
    let mut evt = Event::from_element(&parse(TAKUSER_XML)).unwrap();
    let wire = evt.to_frame().unwrap();
    evt.detail = Some(EventDetail::TakUser(jenny()));
    let rebuilt = evt.to_frame().unwrap();
    // Same content; attribute order of `takv` differs (as_element: os device version platform).
    let (a, b) = (
        parse(std::str::from_utf8(&wire).unwrap()),
        parse(std::str::from_utf8(&rebuilt).unwrap()),
    );
    elements_equal(&a, &b);
    let mut u = jenny();
    u.endpoint = None;
    evt.detail = Some(EventDetail::TakUser(u));
    assert!(evt.to_frame().is_err());
    assert!(evt.to_element().is_err());
}
